import { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { api } from '../core/api/client';
import type { ProviderStatus } from '../core/types';
import { ApiKeyEntry } from './ApiKeyEntry';
import { SetupTokenEntry } from './SetupTokenEntry';
import { ModelSelector } from './ModelSelector';
import { TierPicker } from './TierPicker';
import { OllamaSetup } from './OllamaSetup';
import { TogetherSetup } from './TogetherSetup';
import { IconBrain, IconZap, IconSparkle, IconGlobe, IconHome } from '../shared/icons';

const PROVIDER_ICONS: Record<string, React.ComponentType<{ size?: number; className?: string; strokeWidth?: number }>> = {
  anthropic: IconBrain,
  openai: IconZap,
  deepseek: IconZap,
  kimi: IconSparkle,
  google: IconSparkle,
  together: IconGlobe,
  ollama: IconHome,
};

type AuthTab = 'setup-token' | 'api-key' | 'ollama-setup' | 'together-setup';

const mono = (size: number, color = 'rgba(237,240,244,0.38)') => ({
  fontFamily: "'JetBrains Mono', ui-monospace, monospace",
  fontSize: size, letterSpacing: '0.16em',
  textTransform: 'uppercase' as const, color,
});

export function ProviderSetup() {
  const { t } = useTranslation();

  const [status, setStatus] = useState<ProviderStatus | null>(null);
  const [loading, setLoading] = useState(true);
  const [authTab, setAuthTab] = useState<Record<string, AuthTab>>({});

  function reload() {
    api<ProviderStatus>('/api/providers')
      .then(setStatus)
      .catch(console.error)
      .finally(() => setLoading(false));
  }

  useEffect(() => { reload(); }, []);

  if (loading) return (
    <div style={{ display: 'flex', justifyContent: 'center', padding: '32px 0' }}>
      <div className="w-6 h-6 border-2 border-ch-accent border-t-transparent rounded-full animate-spin" />
    </div>
  );

  const providers = [
    {
      id: 'anthropic',
      name: 'Anthropic (Claude)',
      tabs: [{ id: 'api-key' as AuthTab, label: t('providers.apiKey') }],
      defaultTab: 'api-key' as AuthTab,
    },
    {
      id: 'openai',
      name: 'OpenAI (GPT)',
      tabs: [{ id: 'api-key' as AuthTab, label: t('providers.apiKey') }],
      defaultTab: 'api-key' as AuthTab,
    },
    {
      id: 'deepseek',
      name: 'DeepSeek',
      tabs: [{ id: 'api-key' as AuthTab, label: t('providers.apiKey') }],
      defaultTab: 'api-key' as AuthTab,
    },
    {
      id: 'kimi',
      name: 'Kimi',
      tabs: [{ id: 'api-key' as AuthTab, label: t('providers.apiKey') }],
      defaultTab: 'api-key' as AuthTab,
    },
    {
      id: 'google',
      name: 'Google (Gemini)',
      tabs: [{ id: 'api-key' as AuthTab, label: t('providers.apiKey') }],
      defaultTab: 'api-key' as AuthTab,
    },
    {
      id: 'together',
      name: 'Together AI',
      tabs: [{ id: 'together-setup' as AuthTab, label: t('providers.apiKey') }],
      defaultTab: 'together-setup' as AuthTab,
    },
    ...(!status?.is_railway
      ? [{
          id: 'ollama',
          name: 'Ollama (Local)',
          tabs: [{ id: 'ollama-setup' as AuthTab, label: t('providers.localSetup') }],
          defaultTab: 'ollama-setup' as AuthTab,
        }]
      : []),
  ];

  function getTab(providerId: string): AuthTab {
    return authTab[providerId] || providers.find(p => p.id === providerId)!.defaultTab;
  }

  function renderConnectUI(p: typeof providers[0]) {
    const tab = getTab(p.id);
    return (
      <div>
        {p.tabs.length > 1 && (
          <div style={{ display: 'flex', gap: 8, marginBottom: 12 }}>
            {p.tabs.map(t => (
              <button key={t.id} onClick={() => setAuthTab(prev => ({ ...prev, [p.id]: t.id }))}
                style={{
                  padding: '4px 12px', borderRadius: 4, fontSize: 11, fontWeight: 500,
                  background: tab === t.id ? 'rgba(200,209,217,0.12)' : 'transparent',
                  color: tab === t.id ? '#EDF0F4' : 'rgba(237,240,244,0.62)',
                  border: `1px solid ${tab === t.id ? 'rgba(200,209,217,0.3)' : 'rgba(230,235,242,0.14)'}`,
                  cursor: 'pointer',
                }}
              >{t.label}</button>
            ))}
          </div>
        )}
        {tab === 'setup-token' && <SetupTokenEntry onConnected={reload} />}
        {tab === 'api-key' && <ApiKeyEntry provider={p.id} onConnected={reload} />}
        {tab === 'together-setup' && <TogetherSetup onConnected={reload} />}
        {tab === 'ollama-setup' && <OllamaSetup onConnected={reload} />}
      </div>
    );
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
      {providers.map(p => {
        const profile = status?.profiles?.[p.id];
        const isConnected = profile?.configured ?? false;
        const isActive = status?.active_provider === p.id;
        const currentModel = isActive ? (status?.active_model ?? '') : '';

        return (
          <div key={p.id} style={{
            background: 'rgba(20,24,30,0.78)',
            borderRadius: 6, padding: 20,
            border: `1px solid ${isActive ? 'rgba(200,209,217,0.3)' : 'rgba(230,235,242,0.07)'}`,
          }}>
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 16 }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                <div style={{
                  width: 32, height: 32, borderRadius: 4,
                  background: 'rgba(245,239,227,0.06)',
                  border: '1px solid rgba(230,235,242,0.07)',
                  display: 'flex', alignItems: 'center', justifyContent: 'center',
                  color: 'rgba(237,240,244,0.62)',
                }}>
                  {(() => { const Icon = PROVIDER_ICONS[p.id] || IconGlobe; return <Icon size={16} strokeWidth={1.75} />; })()}
                </div>
                <div>
                <p style={{
                  fontFamily: "'Fraunces', Georgia, serif",
                  fontSize: 16, letterSpacing: '-0.01em', color: '#EDF0F4', margin: 0,
                }}>{p.name}</p>
                {isActive && (
                  <span style={{ ...mono(9, '#D4A85A'), marginTop: 2, display: 'inline-block' }}>
                    {t('providers.active')}
                  </span>
                )}
                </div>
              </div>

              {isConnected && (
                <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                  {profile?.expired && (
                    <span style={{ fontSize: 11, color: '#D4A85A', border: '1px solid rgba(212,168,90,0.3)', borderRadius: 4, padding: '2px 6px' }}>
                      {t('providers.expired')}
                    </span>
                  )}
                  <span style={{ width: 6, height: 6, borderRadius: '50%', background: '#8EA589' }} />
                  <span style={{ ...mono(10, '#8EA589') }}>
                    {t('providers.connected')}
                  </span>
                </div>
              )}
            </div>

            {!isConnected ? renderConnectUI(p) : (
              <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                <ModelSelector provider={p.id} currentModel={currentModel} onChanged={reload} />
                {p.id !== 'ollama' && <TierPicker provider={p.id} onChanged={reload} />}
                {!isActive && (
                  <button onClick={async () => {
                    await api('/api/providers/active', { method: 'PUT', body: JSON.stringify({ provider: p.id, model: currentModel || '' }) });
                    reload();
                  }} style={{
                    width: '100%', padding: '8px 16px', fontSize: 13, borderRadius: 4,
                    border: '1px solid rgba(200,209,217,0.3)', color: 'var(--color-ch-accent, #C8D1D9)',
                    background: 'transparent', cursor: 'pointer',
                  }}>
                    {t('providers.setAsActive')}
                  </button>
                )}
                <button onClick={async () => {
                  await api(`/api/providers/${p.id}/disconnect`, { method: 'POST' });
                  reload();
                }} style={{
                  width: '100%', padding: '8px 16px', fontSize: 13, borderRadius: 4,
                  border: '1px solid rgba(217,119,87,0.3)', color: '#D97757',
                  background: 'transparent', cursor: 'pointer',
                }}>
                  {t('providers.disconnect')}
                </button>
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { api } from '../core/api/client';

interface Props {
  onConnected: () => void;
}

interface OllamaStatus {
  reachable: boolean;
  models: string[];
}

const RECOMMENDED_MODELS = [
  'qwen3.5:4b',
  'qwen3.5:9b',
  'llama3.1:8b',
];

export function OllamaSetup({ onConnected }: Props) {
  const { t } = useTranslation();

  const [status, setStatus] = useState<OllamaStatus | null>(null);
  const [checking, setChecking] = useState(true);
  const [connecting, setConnecting] = useState(false);
  const [error, setError] = useState('');
  const [selectedModel, setSelectedModel] = useState('');
  const [showAdvanced, setShowAdvanced] = useState(false);
  const [customUrl, setCustomUrl] = useState('http://localhost:11434');

  useEffect(() => {
    checkStatus();
  }, []);

  async function checkStatus() {
    setChecking(true);
    try {
      const data = await api<OllamaStatus>('/api/providers/ollama/status');
      setStatus(data);
      if (data.models.length > 0) {
        setSelectedModel(data.models[0]);
      }
    } catch {
      setStatus({ reachable: false, models: [] });
    } finally {
      setChecking(false);
    }
  }

  async function connect() {
    setConnecting(true);
    setError('');
    try {
      await api('/api/providers/ollama/connect', {
        method: 'POST',
        body: JSON.stringify({ base_url: customUrl, model: selectedModel }),
      });
      onConnected();
    } catch (err: unknown) {
      setError(
        err instanceof Error
          ? err.message
          : t('providers.ollamaConnectFailed')
      );
    } finally {
      setConnecting(false);
    }
  }

  if (checking) {
    return (
      <div className="flex items-center gap-2 py-4">
        <div className="w-4 h-4 border-2 border-ch-accent border-t-transparent rounded-full animate-spin" />
        <span className="text-sm text-ch-ink-mute">
          {t('providers.ollamaDetecting')}
        </span>
      </div>
    );
  }

  // Ollama detected with models installed
  if (status?.reachable && status.models.length > 0) {
    return (
      <div className="space-y-3">
        <div className="flex items-center gap-2">
          <span className="w-2 h-2 bg-green-400 rounded-full" />
          <span className="text-sm text-green-400">
            {t('providers.ollamaDetected')}
          </span>
        </div>

        <div>
          <label className="block text-xs text-ch-ink-mute mb-1.5">{t('providers.selectModel')}</label>
          <select
            value={selectedModel}
            onChange={e => setSelectedModel(e.target.value)}
            className="w-full bg-ch-bg-raised border border-ch-line-strong text-white rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-amber-500"
          >
            {status.models.map(m => (
              <option key={m} value={m}>{m}</option>
            ))}
          </select>
        </div>

        {error && <p className="text-red-400 text-xs">{error}</p>}

        <button
          onClick={connect}
          disabled={connecting || !selectedModel}
          className="w-full py-2.5 bg-brand text-white text-sm font-semibold rounded-lg hover:opacity-90 transition disabled:opacity-50"
        >
          {connecting
            ? t('providers.connecting')
            : t('providers.connect')}
        </button>
      </div>
    );
  }

  // Ollama detected but no models
  if (status?.reachable && status.models.length === 0) {
    return (
      <div className="space-y-3">
        <div className="flex items-center gap-2">
          <span className="w-2 h-2 bg-yellow-400 rounded-full" />
          <span className="text-sm text-yellow-400">
            {t('providers.ollamaNoModels')}
          </span>
        </div>

        <p className="text-xs text-ch-ink-mute">
          {t('providers.ollamaPullHint')}
        </p>

        <div className="space-y-2">
          {RECOMMENDED_MODELS.map(model => (
            <div key={model} className="bg-ch-bg-card rounded-lg px-3 py-2">
              <code className="text-xs text-ch-gold">
                ollama pull {model}
              </code>

              <p className="text-xs text-ch-ink-dim mt-0.5">
                {model === 'qwen3.5:4b' && t('providers.ollamaModelLight')}
                {model === 'qwen3.5:9b' && t('providers.ollamaModelBalanced')}
                {model === 'llama3.1:8b' && t('providers.ollamaModelQuality')}
              </p>
            </div>
          ))}
        </div>

        <button
          onClick={checkStatus}
          className="w-full py-2.5 bg-brand text-white text-sm font-semibold rounded-lg hover:opacity-90 transition"
        >
          {t('providers.refresh')}
        </button>
      </div>
    );
  }

  // Ollama not detected
  return (
    <div className="space-y-3">
      <div className="flex items-center gap-2">
        <span className="w-2 h-2 bg-red-400 rounded-full" />
        <span className="text-sm text-red-400">
          {t('providers.ollamaNotDetected')}
        </span>
      </div>

      <div className="bg-ch-bg-card rounded-lg px-4 py-3 space-y-2">
        <p className="text-sm text-ch-ink-mute">
          {t('providers.ollamaLocalIntro')}
        </p>
        <ol className="text-xs text-ch-ink-mute space-y-1 list-decimal list-inside">
          <li>
            {t('providers.ollamaInstallStep')}{' '}
            <a
              href="https://ollama.com"
              target="_blank"
