      tabs: [{ id: 'api-key' as AuthTab, label: t('providers.apiKey') }], defaultTab: 'api-key' },
    { id: 'google', name: 'Google (Gemini)', kind: 'cloud',
      tabs: [{ id: 'api-key' as AuthTab, label: t('providers.apiKey') }], defaultTab: 'api-key' },
    { id: 'together', name: 'Together AI', kind: 'cloud',
      tabs: [{ id: 'together-setup' as AuthTab, label: t('providers.apiKey') }], defaultTab: 'together-setup' },
    ...(!status?.is_railway
      ? [{ id: 'ollama', name: 'Ollama (Local)', kind: 'local' as const,
          tabs: [{ id: 'ollama-setup' as AuthTab, label: t('providers.localSetup') }], defaultTab: 'ollama-setup' as AuthTab }]
      : []),
  ];

